# Tests for extractable first-stage model objects (Ticket S1)
# Verifies coefficients, VCV, RMSE against Stata `savefirst` CSV fixtures
# generated by generate-firststage-fixtures.do
#
# M-25 fixture re-base (planning/22-spec-matrix.md): this family moved off
# the Card ad hoc data onto the canonical help-file bases (mroz, griliches76,
# abdata). The retired LIML config is dropped entirely -- estimator-invariance
# of the first-stage object is now covered by the fixture-free identity test
# "first stage is estimator-invariant" in test-diagnostics-firststage.R.

# --- Bundled datasets (lazy-loaded with the package) ---
data(mroz, package = "ivreg2r")
data(griliches, package = "ivreg2r")
data(abdata, package = "ivreg2r")

mroz_formula <- lwage ~ exper + expersq | educ | age + kidslt6 + kidsge6
# mroz_justid_formula comes from helper-fixtures.R.

# gril_formula (H06, help.txt:1154) is now provided by helper-fixtures.R.

# ============================================================================
# Fixture readers
# ============================================================================

skip_if_no_fs_fixtures <- function(prefix, suffixes = c("coef", "vcov", "scalars")) {
  for (s in suffixes) {
    path <- fixture_path(paste0(prefix, "_", s, ".csv"))
    skip_if_not(file.exists(path), "Stata fixture not available")
  }
}

read_fs_coef <- function(prefix) {
  fx <- read.csv(fixture_path(paste0(prefix, "_coef.csv")),
                 strip.white = TRUE)
  vals <- fx$estimate
  nms <- ifelse(fx$term == "_cons", "(Intercept)", fx$term)
  names(vals) <- nms
  vals
}

read_fs_vcov <- function(prefix) {
  read_vcov_fixture(fixture_path(paste0(prefix, "_vcov.csv")))
}

read_fs_scalars <- function(prefix) {
  read_scalar_fixture(fixture_path(paste0(prefix, "_scalars.csv")))
}

# ============================================================================
# Tests: API and structure
# ============================================================================

test_that("first_stage() errors informatively without flag", {
  fit <- ivreg2(mroz_formula, data = mroz)
  expect_error(first_stage(fit), "Re-fit with `first_stage = TRUE`")
})

test_that("first_stage() errors for OLS models", {
  fit_ols <- ivreg2(lwage ~ exper + expersq, data = mroz,
                     first_stage = TRUE)
  expect_error(first_stage(fit_ols), "Re-fit with `first_stage = TRUE`")
})

test_that("first_stage returns correct class and structure", {
  fit <- ivreg2(mroz_formula, data = mroz, first_stage = TRUE)
  fs <- first_stage(fit)
  expect_type(fs, "list")
  expect_named(fs, "educ")
  expect_s3_class(fs$educ, "ivreg2_first_stage")

  expect_length(coef(fs$educ), 6L)
  expect_equal(dim(vcov(fs$educ)), c(6L, 6L))
  expect_length(residuals(fs$educ), fit$nobs)
  expect_length(fitted(fs$educ), fit$nobs)
  expect_equal(nobs(fs$educ), fit$nobs)
})


# ============================================================================
# Tests: Stata parity — coefficients, VCV, scalars
# ============================================================================

test_that("first_stage matches Stata (mroz, IID)", {
  skip_if_no_fs_fixtures("fs_mroz_iid")
  fit <- ivreg2(mroz_formula, data = mroz, first_stage = TRUE)
  fs <- first_stage(fit)$educ

  stata_coef <- read_fs_coef("fs_mroz_iid")
  stata_vcov <- read_fs_vcov("fs_mroz_iid")
  stata_sc <- read_fs_scalars("fs_mroz_iid")

  for (nm in names(stata_coef)) {
    expect_equal(coef(fs)[[nm]], stata_coef[[nm]], tolerance = stata_tol$coef,
                 label = paste0("coef [", nm, "]"))
  }
  expect_vcov_equal(vcov(fs), stata_vcov, tol = stata_tol$vcov)
  expect_equal(fs$sigma, stata_sc$rmse, tolerance = stata_tol$coef)
  expect_equal(fs$df.residual, as.integer(stata_sc$df_r))
})

test_that("first_stage matches Stata (mroz, robust)", {
  skip_if_no_fs_fixtures("fs_mroz_robust", c("vcov", "scalars"))
  fit <- ivreg2(mroz_formula, data = mroz, vcov = "robust",
                first_stage = TRUE)
  fs <- first_stage(fit)$educ

  stata_vcov <- read_fs_vcov("fs_mroz_robust")
  stata_sc <- read_fs_scalars("fs_mroz_robust")

  # No fs_mroz_robust_coef fixture is shipped: the saved first-stage OLS coefficients are VCE-invariant (the robust coef file was verified byte-identical to the iid one at re-base, and the generator's nocoef option skips the duplicate), so the robust fit's coefficients are compared against the iid coef fixture.
  stata_coef <- read_fs_coef("fs_mroz_iid")
  for (nm in names(stata_coef)) {
    expect_equal(coef(fs)[[nm]], stata_coef[[nm]], tolerance = stata_tol$coef,
                 label = paste0("coef [", nm, "]"))
  }
  expect_vcov_equal(vcov(fs), stata_vcov, tol = stata_tol$vcov)
  expect_equal(fs$sigma, stata_sc$rmse, tolerance = stata_tol$coef)
  expect_equal(fs$df.residual, as.integer(stata_sc$df_r))
})

