# ============================================================================
# Tests: broom methods
# ============================================================================

test_that("tidy() and glance() work for first-stage objects", {
  fit <- ivreg2(mroz_formula, data = mroz, vcov = "robust",
                first_stage = TRUE)
  fs <- first_stage(fit)$educ

  td <- tidy(fs)
  expect_s3_class(td, "tbl_df")
  expect_equal(nrow(td), 6L)
  expect_true(all(c("term", "estimate", "std.error", "statistic", "p.value",
                     "conf.low", "conf.high") %in% names(td)))

  gl <- glance(fs)
  expect_s3_class(gl, "tbl_df")
  expect_equal(nrow(gl), 1L)
  expect_true("sigma" %in% names(gl))
  expect_true("f_stat" %in% names(gl))
  expect_true("partial_r2" %in% names(gl))
})

test_that("tidy(exponentiate = TRUE) works for first-stage objects", {
  fit <- ivreg2(mroz_formula, data = mroz, first_stage = TRUE)
  fs <- first_stage(fit)$educ

  td_raw <- tidy(fs, conf.int = TRUE)
  td_exp <- tidy(fs, conf.int = TRUE, exponentiate = TRUE)
  expect_equal(td_exp$estimate, exp(td_raw$estimate))
  expect_equal(td_exp$conf.low, exp(td_raw$conf.low))
  expect_equal(td_exp$conf.high, exp(td_raw$conf.high))
  expect_equal(td_exp$std.error, td_raw$std.error)
})


