test_that("summary() and print() work for first-stage objects", {
  fit <- ivreg2(mroz_formula, data = mroz, first_stage = TRUE)
  fs <- first_stage(fit)$educ

  s <- summary(fs)
  expect_s3_class(s, "summary.ivreg2_first_stage")

  out <- capture.output(print(s))
  expect_true(any(grepl("First-stage regression", out)))
  expect_true(any(grepl("Root MSE", out)))

  out2 <- capture.output(print(fs))
  expect_true(any(grepl("First-stage regression", out2)))
})

test_that("confint() works for first-stage objects", {
  fit <- ivreg2(mroz_formula, data = mroz, first_stage = TRUE)
  fs <- first_stage(fit)$educ

  ci <- confint(fs)
  expect_equal(nrow(ci), 6L)
  expect_equal(ncol(ci), 2L)

  ci2 <- confint(fs, parm = "kidslt6")
  expect_equal(nrow(ci2), 1L)
})


# ============================================================================
# Tests: Codex review bug fixes
# ============================================================================

test_that("clustered first-stage df.residual is M-1, not N-L", {
  fit <- ivreg2(ab_formula, data = abdata, tvar = "year", ivar = "id",
                clusters = ~id, first_stage = TRUE)
  fs <- first_stage(fit)$w

  # M=140 clusters on id, so df.residual should be M-1 = 139
  expect_equal(fs$df.residual, 139L)

  # summary/tidy/confint should use df=139, not the raw residual df
  s <- summary(fs)
  p_from_summary <- s$coef_table["(Intercept)", "Pr(>|t|)"]
  p_if_wrong_df <- 2 * pt(-abs(s$coef_table["(Intercept)", "t value"]),
                           df = fit$nobs)
  expect_true(p_from_summary > p_if_wrong_df)

  # confint should be wider with df=139 than with the raw residual df
  ci <- confint(fs, parm = "(Intercept)")
  ci_width <- ci[1, 2] - ci[1, 1]
  crit_wrong <- qt(0.025, df = fit$nobs)
  se_intercept <- sqrt(vcov(fs)["(Intercept)", "(Intercept)"])
  width_wrong <- -2 * crit_wrong * se_intercept
  expect_true(ci_width > width_wrong)
})

test_that("HAC first-stage residuals are in original row order", {
  data(phillips, package = "ivreg2r")
  # Deliberately shuffle row order so sorted != original
  set.seed(42)
  phillips_shuffled <- phillips[sample(nrow(phillips)), ]

  fit <- ivreg2(cinf ~ unem | inf_1 | inf_2,
                data = phillips_shuffled, vcov = "HAC",
                kernel = "bartlett", bw = 3,
                tvar = "year",
                first_stage = TRUE)
  fs <- first_stage(fit)$inf_1

  # First-stage residuals + fitted should sum to the endogenous variable
  # in the correct (shuffled) row order. Use the model frame to get the
  # observations actually used (after NA removal).
  mf <- model.frame(fit)
  inf1_used <- mf$inf_1
  recon <- unname(fitted(fs) + residuals(fs))
  expect_equal(recon, inf1_used, tolerance = 1e-10)

  # Also verify alignment with main model residuals (both should be
  # in original row order)
  expect_equal(length(residuals(fs)), length(residuals(fit)))
})


# ============================================================================
# Tests: no regressions
# ============================================================================

test_that("first_stage = FALSE (default) doesn't change existing behavior", {
  fit1 <- ivreg2(mroz_formula, data = mroz)
  fit2 <- ivreg2(mroz_formula, data = mroz, first_stage = TRUE)

  expect_equal(coef(fit1), coef(fit2))
  expect_equal(vcov(fit1), vcov(fit2))
  expect_equal(fit1$sigma, fit2$sigma)
  expect_equal(fit1$first_stage, fit2$first_stage)
})
